{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"const TERMINAL_STATUSES = new Set(['timeout', 'crashed', 'skipped', 'missing']);

function ratio(numerator, denominator) {
  return denominator === 0 ? null : Number((numerator / denominator).toFixed(6));
}

function normalizeTrial(trial) {
  if (typeof trial === 'string') return { status: trial };
  return {
    status: trial?.status ?? trial?.outcome ?? 'missing',
    reason: trial?.reason ?? null,
  };
}

function normalizeCase(input, index) {
  const trials = Array.isArray(input?.trials) ? input.trials.map(normalizeTrial) : [];
  const status = input?.status ?? (trials.length === 0 ? 'missing' : undefined);
  return {
    id: input?.id ?? `case-${index + 1}`,
    scenarioId: input?.scenarioId ?? null,
    kind: input?.kind ?? 'standard',
    safety: Boolean(input?.safety),
    status,
    trials,
  };
}

function isPassed(status) {
  return status === 'passed' || status === 'pass';
}

function isRejected(status) {
  return status === 'rejected' || status === 'reject';
}

function isFailed(status) {
  return status === 'failed' || status === 'fail';
}

function hasTerminalStatus(item) {
  return TERMINAL_STATUSES.has(item.status) || item.trials.some((trial) => TERMINAL_STATUSES.has(trial.status));
}

function firstFailure(caseItem) {
  const index = caseItem.trials.findIndex((trial) => isFailed(trial.status));
  if (index < 0) return null;
  return { trial: index + 1, status: caseItem.trials[index].status, reason: caseItem.trials[index].reason };
}

function isFlake(caseItem, k) {
  if (caseItem.trials.length !== k || hasTerminalStatus(caseItem)) return false;
  if (!isFailed(caseItem.trials[0].status)) return false;
  return caseItem.trials.slice(1).every((trial) => isPassed(trial.status));
}

function anchorViolation(caseItem) {
  if (caseItem.kind === 'positive') {
    return caseItem.trials.length !== caseItem.expectedK
      ? 'positive anchor does not have the registered number of trials'
      : caseItem.trials.every((trial) => isPassed(trial.status))
        ? null
        : 'positive anchor contains a trial that did not pass';
  }
  if (caseItem.kind === 'negative') {
    return caseItem.trials.length !== caseItem.expectedK
      ? 'negative anchor does not have the registered number of trials'
      : caseItem.trials.every((trial) => isRejected(trial.status))
        ? null
        : 'negative anchor contains a trial that was not rejected';
  }
  return null;
}

/**
 * Aggregates a deterministic Agent Dev reliability fixture.
 *
 * Metric denominators contain complete cases only. Incomplete cases (missing,
 * timeout, crash, skip, or an incomplete trial vector) remain in the raw
 * denominator and are explicitly retained in the result. This module has no
 * provider, network, timer, or runtime side effects.
 */
export function aggregateReliability(fixture) {
  const k = Number(fixture?.k);
  const minCases = Number(fixture?.minCases);
  const flakeThreshold = Number(fixture?.flakeThreshold);
  if (!Number.isInteger(k) || k < 1) throw new TypeError('fixture.k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 1) throw new TypeError('fixture.minCases must be a positive integer');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('fixture.flakeThreshold must be between 0 and 1');
  }

  const cases = (fixture?.cases ?? []).map((item, index) => ({
    ...normalizeCase(item, index),
    expectedK: k,
  }));
  const incompleteReasons = new Map();
  const caseResults = cases.map((caseItem) => {
    const reasons = [];
    if (caseItem.status && TERMINAL_STATUSES.has(caseItem.status)) reasons.push(caseItem.status);
    if (caseItem.trials.length !== k) reasons.push('trial-count-mismatch');
    for (const trial of caseItem.trials) {
      if (TERMINAL_STATUSES.has(trial.status)) reasons.push(trial.status);
    }
    const uniqueReasons = [...new Set(reasons)];
    const complete = uniqueReasons.length === 0 && caseItem.trials.length === k;
    const passedCount = caseItem.trials.filter((trial) => isPassed(trial.status)).length;
    const flake = complete && isFlake(caseItem, k);
    const failure = complete ? firstFailure(caseItem) : null;
    const anchor = anchorViolation(caseItem);
    const safetyViolation = caseItem.safety && (uniqueReasons.length > 0 || flake)
      ? `safety case ${caseItem.id} contains ${uniqueReasons.join(', ') || 'a flake'}`
      : null;
    if (!complete) incompleteReasons.set(caseItem.id, uniqueReasons);
    return {
      id: caseItem.id,
      scenarioId: caseItem.scenarioId,
      kind: caseItem.kind,
      safety: caseItem.safety,
      complete,
      incompleteReasons: uniqueReasons,
      trials: caseItem.trials,
      passedCount,
      passAtK: complete && passedCount > 0,
      passPowerK: complete && passedCount === k,
      flake,
      firstFailure: failure,
      anchorViolation: anchor,
      safetyViolation,
    };
  });

  const completeResults = caseResults.filter((item) => item.complete);
  const incompleteResults = caseResults.filter((item) => !item.complete);
  const passPowerNumerator = completeResults.filter((item) => item.passPowerK).length;
  const passAtNumerator = completeResults.filter((item) => item.passAtK).length;
  const flakeNumerator = completeResults.filter((item) => item.flake).length;
  const trialRates = [];
  for (let index = 0; index < k; index += 1) {
    const rawAttempts = cases.flatMap((item) => item.trials.filter((_, trialIndex) => trialIndex === index));
    const completeAttempts = completeResults.flatMap((item) => item.trials.filter((_, trialIndex) => trialIndex === index));
    const rawPassed = rawAttempts.filter((trial) => isPassed(trial.status)).length;
    const completePassed = completeAttempts.filter((trial) => isPassed(trial.status)).length;
    trialRates.push({
      trial: index + 1,
      rawPassed,
      rawAttempts: rawAttempts.length,
      rawSuccessRate: ratio(rawPassed, rawAttempts.length),
      completePassed,
      completeAttempts: completeAttempts.length,
      completeSuccessRate: ratio(completePassed, completeAttempts.length),
    });
  }

  const anchorViolations = caseResults
    .filter((item) => item.anchorViolation)
    .map((item) => ({ id: item.id, reason: item.anchorViolation }));
  const safetyViolations = caseResults
    .filter((item) => item.safetyViolation)
    .map((item) => ({ id: item.id, reason: item.safetyViolation }));
  const reasons = [];
  if (anchorViolations.length > 0) reasons.push('anchor violation');
  if (safetyViolations.length > 0) reasons.push('safety violation');
  const flakeRate = ratio(flakeNumerator, completeResults.length);
  if (flakeRate !== null && flakeRate > flakeThreshold) reasons.push('flake threshold exceeded');
  let gate = 'pass';
  if (anchorViolations.length > 0 || safetyViolations.length > 0 || (flakeRate !== null && flakeRate > flakeThreshold)) {
    gate = 'fail';
  } else if (completeResults.length < minCases) {
    gate = 'insufficient-sample';
    reasons.push(`complete cases ${completeResults.length} < ${minCases}`);
  }

  return {
    oracle: 'deterministic-fixture',
    providerClaim: false,
    humanClaim: false,
    generalizationClaim: false,
    design: { k, minCases, flakeThreshold },
    raw: {
      caseCount: cases.length,
      trialCount: cases.reduce((sum, item) => sum + item.trials.length, 0),
      completeCaseCount: completeResults.length,
      incompleteCaseCount: incompleteResults.length,
    },
    metrics: {
      passPowerK: {
        numerator: passPowerNumerator,
        denominator: completeResults.length,
        rate: ratio(passPowerNumerator, completeResults.length),
      },
      passAtK: {
        numerator: passAtNumerator,
        denominator: completeResults.length,
        rate: ratio(passAtNumerator, completeResults.length),
      },
      flake: {
        numerator: flakeNumerator,
        denominator: completeResults.length,
        rate: flakeRate,
        threshold: flakeThreshold,
      },
      trialSuccessRates: trialRates,
    },
    incomplete: incompleteResults.map((item) => ({
      id: item.id,
      scenarioId: item.scenarioId,
      kind: item.kind,
      safety: item.safety,
      reasons: item.incompleteReasons,
      trials: item.trials,
    })),
    anchors: {
      positive: caseResults.filter((item) => item.kind === 'positive').map((item) => ({
        id: item.id,
        ok: item.anchorViolation === null,
        reason: item.anchorViolation,
      })),
      negative: caseResults.filter((item) => item.kind === 'negative').map((item) => ({
        id: item.id,
        ok: item.anchorViolation === null,
        reason: item.anchorViolation,
      })),
    },
    safetyViolations,
    gate,
    reasons,
    cases: caseResults,
  };
}

export const aggregateReliabilityFixture = aggregateReliability;

export function renderReliabilityMarkdown(result) {
  const metrics = result.metrics;
  const trials = metrics.trialSuccessRates.map((item) => (
    `| ${item.trial} | ${item.completePassed}/${item.completeAttempts} | ${item.completeSuccessRate === null ? 'n/a' : item.completeSuccessRate} | ${item.rawPassed}/${item.rawAttempts} | ${item.rawSuccessRate === null ? 'n/a' : item.rawSuccessRate} |`
  )).join('\n');
  const incomplete = result.incomplete.map((item) => (
    `| ${item.id} | ${item.reasons.join(', ')} | ${item.trials.map((trial) => trial.status).join(', ') || 'no trials'} |`
  )).join('\n');
  const anchors = [...result.anchors.positive, ...result.anchors.negative].map((item) => (
    `| ${item.id} | ${item.ok ? 'ok' : 'fail'} | ${item.reason ?? '-'} |`
  )).join('\n');
  return `## Deterministic Reliability Aggregation

Oracle: ${result.oracle}; no claim is made about a real provider, human users, or generalization.

| Metric | Numerator | Denominator | Rate |
| --- | ---: | ---: | ---: |
| pass^k (all k passed) | ${metrics.passPowerK.numerator} | ${metrics.passPowerK.denominator} | ${metrics.passPowerK.rate ?? 'n/a'} |
| pass@k (at least one passed) | ${metrics.passAtK.numerator} | ${metrics.passAtK.denominator} | ${metrics.passAtK.rate ?? 'n/a'} |
| flake | ${metrics.flake.numerator} | ${metrics.flake.denominator} | ${metrics.flake.rate ?? 'n/a'} |
| Raw cases | - | ${result.raw.caseCount} | - |
| Complete cases | - | ${result.raw.completeCaseCount} | - |
| Incomplete cases | - | ${result.raw.incompleteCaseCount} | - |

Gate: **${result.gate}**. Reasons: ${result.reasons.length ? result.reasons.join('; ') : 'none'}.

### Per-trial success

| Trial | Complete numerator/denominator | Complete rate | Raw numerator/denominator | Raw rate |
| ---: | ---: | ---: | ---: | ---: |
${trials}

### Incomplete cases retained

| Case | Reason | Trial statuses |
| --- | --- | --- |
${incomplete}

### Anchors

| Anchor | Result | Reason |
| --- | --- | --- |
${anchors}
`;
}
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityTrialStatus =
  | 'passed'
  | 'pass'
  | 'failed'
  | 'fail'
  | 'rejected'
  | 'reject'
  | 'timeout'
  | 'crashed'
  | 'skipped'
  | 'missing';

export interface ReliabilityTrial {
  status: ReliabilityTrialStatus | string;
  reason?: string | null;
}

export interface ReliabilityFixtureCase {
  id: string;
  scenarioId?: string | null;
  kind?: 'standard' | 'positive' | 'negative' | string;
  safety?: boolean;
  status?: ReliabilityTrialStatus | string;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  k: number;
  minCases: number;
  flakeThreshold: number;
  cases: ReliabilityFixtureCase[];
}

export interface ReliabilityRatio {
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface ReliabilityTrialRate {
  trial: number;
  rawPassed: number;
  rawAttempts: number;
  rawSuccessRate: number | null;
  completePassed: number;
  completeAttempts: number;
  completeSuccessRate: number | null;
}

export interface ReliabilityCaseResult {
  id: string;
  scenarioId: string | null;
  kind: string;
  safety: boolean;
  complete: boolean;
  incompleteReasons: string[];
  trials: ReliabilityTrial[];
  passedCount: number;
  passAtK: boolean;
  passPowerK: boolean;
  flake: boolean;
  firstFailure: { trial: number; status: string; reason: string | null } | null;
  anchorViolation: string | null;
  safetyViolation: string | null;
}

export interface ReliabilityResult {
  oracle: 'deterministic-fixture';
  providerClaim: false;
  humanClaim: false;
  generalizationClaim: false;
  design: { k: number; minCases: number; flakeThreshold: number };
  raw: { caseCount: number; trialCount: number; completeCaseCount: number; incompleteCaseCount: number };
  metrics: {
    passPowerK: ReliabilityRatio;
    passAtK: ReliabilityRatio;
    flake: ReliabilityRatio & { threshold: number };
    trialSuccessRates: ReliabilityTrialRate[];
  };
  incomplete: Array<{
    id: string;
    scenarioId: string | null;
    kind: string;
    safety: boolean;
    reasons: string[];
    trials: ReliabilityTrial[];
  }>;
  anchors: {
    positive: Array<{ id: string; ok: boolean; reason: string | null }>;
    negative: Array<{ id: string; ok: boolean; reason: string | null }>;
  };
  safetyViolations: Array<{ id: string; reason: string }>;
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityCaseResult[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityResult;
export const aggregateReliabilityFixture: typeof aggregateReliability;
