    `| ${item.trial} | ${item.completePassed}/${item.completeAttempts} | ${item.completeSuccessRate === null ? 'n/a' : item.completeSuccessRate} | ${item.rawPassed}/${item.rawAttempts} | ${item.rawSuccessRate === null ? 'n/a' : item.rawSuccessRate} |`
  )).join('\n');
  const incomplete = result.incomplete.map((item) => (
    `| ${item.id} | ${item.reasons.join(', ')} | ${item.trials.map((trial) => trial.status).join(', ') || 'no trials'} |`
  )).join('\n');
  const anchors = [...result.anchors.positive, ...result.anchors.negative].map((item) => (
    `| ${item.id} | ${item.ok ? 'ok' : 'fail'} | ${item.reason ?? '-'} |`
  )).join('\n');
  return `## Deterministic Reliability Aggregation

Oracle: ${result.oracle}; no claim is made about a real provider, human users, or generalization.

| Metric | Numerator | Denominator | Rate |
| --- | ---: | ---: | ---: |
| pass^k (all k passed) | ${metrics.passPowerK.numerator} | ${metrics.passPowerK.denominator} | ${metrics.passPowerK.rate ?? 'n/a'} |
| pass@k (at least one passed) | ${metrics.passAtK.numerator} | ${metrics.passAtK.denominator} | ${metrics.passAtK.rate ?? 'n/a'} |
| flake | ${metrics.flake.numerator} | ${metrics.flake.denominator} | ${metrics.flake.rate ?? 'n/a'} |
| Raw cases | - | ${result.raw.caseCount} | - |
| Complete cases | - | ${result.raw.completeCaseCount} | - |
| Incomplete cases | - | ${result.raw.incompleteCaseCount} | - |

Gate: **${result.gate}**. Reasons: ${result.reasons.length ? result.reasons.join('; ') : 'none'}.

### Per-trial success

| Trial | Complete numerator/denominator | Complete rate | Raw numerator/denominator | Raw rate |
| ---: | ---: | ---: | ---: | ---: |
${trials}

### Incomplete cases retained

| Case | Reason | Trial statuses |
| --- | --- | --- |
${incomplete}

### Anchors

| Anchor | Result | Reason |
| --- | --- | --- |
${anchors}
`;
}
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityTrialStatus =
  | 'passed'
  | 'pass'
  | 'failed'
  | 'fail'
  | 'rejected'
  | 'reject'
  | 'timeout'
  | 'crashed'
  | 'skipped'
  | 'missing';

export interface ReliabilityTrial {
  status: ReliabilityTrialStatus | string;
  reason?: string | null;
}

export interface ReliabilityFixtureCase {
  id: string;
  scenarioId?: string | null;
  kind?: 'standard' | 'positive' | 'negative' | string;
  safety?: boolean;
  status?: ReliabilityTrialStatus | string;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  k: number;
  minCases: number;
  flakeThreshold: number;
  cases: ReliabilityFixtureCase[];
}

export interface ReliabilityRatio {
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface ReliabilityTrialRate {
  trial: number;
  rawPassed: number;
  rawAttempts: number;
  rawSuccessRate: number | null;
  completePassed: number;
  completeAttempts: number;
  completeSuccessRate: number | null;
}

export interface ReliabilityCaseResult {
  id: string;
  scenarioId: string | null;
  kind: string;
  safety: boolean;
  complete: boolean;
  incompleteReasons: string[];
  trials: ReliabilityTrial[];
  passedCount: number;
  passAtK: boolean;
  passPowerK: boolean;
  flake: boolean;
  firstFailure: { trial: number; status: string; reason: string | null } | null;
  anchorViolation: string | null;
  safetyViolation: string | null;
}

export interface ReliabilityResult {
  oracle: 'deterministic-fixture';
  providerClaim: false;
  humanClaim: false;
  generalizationClaim: false;
  design: { k: number; minCases: number; flakeThreshold: number };
  raw: { caseCount: number; trialCount: number; completeCaseCount: number; incompleteCaseCount: number };
  metrics: {
    passPowerK: ReliabilityRatio;
    passAtK: ReliabilityRatio;
    flake: ReliabilityRatio & { threshold: number };
    trialSuccessRates: ReliabilityTrialRate[];
  };
  incomplete: Array<{
    id: string;
    scenarioId: string | null;
    kind: string;
    safety: boolean;
    reasons: string[];
    trials: ReliabilityTrial[];
  }>;
  anchors: {
    positive: Array<{ id: string; ok: boolean; reason: string | null }>;
    negative: Array<{ id: string; ok: boolean; reason: string | null }>;
  };
  safetyViolations: Array<{ id: string; reason: string }>;
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityCaseResult[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityResult;
export const aggregateReliabilityFixture: typeof aggregateReliability;
export function renderReliabilityMarkdown(result: ReliabilityResult): string;
