      id: caseItem.id,
      scenarioId: caseItem.scenarioId,
      kind: caseItem.kind,
      safety: caseItem.safety,
      complete,
      incompleteReasons: uniqueReasons,
      trials: caseItem.trials,
      passedCount,
      passAtK: complete && passedCount > 0,
