  const anchorViolations = caseResults
    .filter((item) => item.anchorViolation)
    .map((item) => ({ id: item.id, reason: item.anchorViolation }));
  const safetyViolations = caseResults
    .filter((item) => item.safetyViolation)
    .map((item) => ({ id: item.id, reason: item.safetyViolation }));
  const reasons = [];
  if (anchorViolations.length > 0) reasons.push('anchor violation');
  if (safetyViolations.length > 0) reasons.push('safety violation');
  const flakeRate = ratio(flakeNumerator, completeResults.length);
  if (flakeRate !== null && flakeRate > flakeThreshold) reasons.push('flake threshold exceeded');
  let gate = 'pass';
  if (anchorViolations.length > 0 || safetyViolations.length > 0 || (flakeRate !== null && flakeRate > flakeThreshold)) {
    gate = 'fail';
