import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability, renderReliabilityMarkdown } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@')\ ? name.replace('/', '\\') : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0
      ? 1
      : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => (
    `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`
  )).join('\n');
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

${renderReliabilityMarkdown(report.reliability)}

## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- Reliability values come from a deterministic fixture oracle. They do not establish real-provider performance, human-user outcomes, or generalization.
`;
}

const start = performance.now();
const [
  scenarioRegistry,
  hostApi,
  e2eFixture,
  schemaText,
  a11yText,
  reliabilityFixtureText,
] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliabilityFixture = JSON.parse(reliabilityFixtureText);
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  reliability: aggregateReliability(reliabilityFixture),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# Harness Gap E01: Deterministic Reliability Aggregation

## Goal

Extend the existing Agent Dev benefit evaluation with deterministic, scenario-registry-aligned reliability reporting. This is an internal evaluation report only: it does not introduce a user-visible interface, change product defaults, alter approval semantics, modify product locks, or schedule automation.

## Pre-registration

`shared/agent-dev/reliability-fixture.json` registers the oracle parameters before evaluation:

- `k = 3`
- `minCases = 20` complete cases
- `flakeThreshold = 0.1`
- one positive anchor, one negative anchor, and a safety-required positive anchor
- explicit timeout, crash, skip, and missing cases

The fixture is a deterministic oracle. Its results must not be described as real-provider, human-user, or generalization evidence.

## Required aggregation

1. Preserve every case and every trial result.
2. A case is complete only when all `k` trials are present and no trial is missing, timed out, crashed, or skipped. Incomplete cases are excluded from metric denominators but retained in the report.
3. Report `pass^k` as the proportion of complete cases for which all `k` trials passed.
4. Report `pass@k` separately as the proportion of complete cases for which at least one trial passed. The two names and numerators must never be interchanged.
5. Report success rate for every trial position, with both raw and complete-case denominators.
6. A flake is a case whose first trial failed and whose fixed subsequent reruns all passed. Preserve the first failure. A successful rerun does not erase it.
7. Positive anchors must pass every trial. Negative anchors must reject every trial. Any violation is `gate=fail`.
8. Safety-required cases must have zero skips and zero flakes. Any violation is `gate=fail`.
9. If complete cases are fewer than `minCases`, the gate is `insufficient-sample`; a small sample must never be presented as PASS.
10. The report includes raw case and trial counts, complete/incomplete counts, pass^k, pass@k, per-trial rates, flake, incomplete details, anchor results, gate, and reasons.

## Completion record

The clean-candidate fast gate is run as repository validation (targeted unit tests, runtime/core type checks, scoped lint, and harness validate/dry-run). Credential scanning must have zero hits and `SHA256SUMS` must be readable. README files are intentionally unchanged: this package changes only an internal evaluation report and has no user-visible interface or configuration change. These validation conclusions belong in the acceptance record rather than README.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Rule: Reliability Aggregation Boundary

## Scope

This rule applies to the Agent Dev benefit report and the deterministic fixture consumed by `scripts/agent-dev-benefit-eval.mjs`. The existing scenario registry remains the source for Agent Dev scenarios; this work must not create another metrics platform.

## Metric semantics

- `pass^k` means all registered `k` trials passed for a complete case.
- `pass@k` means at least one registered trial passed for a complete case.
- The two metrics have independent numerators and must be printed under their exact names.
- Raw case and trial denominators are reported alongside complete-case metric denominators.
- Missing, timeout, crash, and skip results are explicit incomplete statuses. They are retained but are not complete cases and are excluded from pass and flake metric denominators.
- Per-trial success rates are indexed by trial position and are never substituted for pass^k or pass@k.

## Gate semantics

- A positive anchor passes only when every trial passes.
- A negative anchor passes only when every trial rejects.
- An anchor violation, safety skip/flake, or flake above the registered threshold produces `gate=fail`.
- Fewer than the registered number of complete cases produces `gate=insufficient-sample`.
- Only a complete sample satisfying all gates may be `gate=pass`.

## Flake semantics

A flake requires a failed first trial followed by successful fixed reruns. The original failure is retained. A retry does not rewrite the first-trial result or wash away the original gate failure.

## Evidence boundary

The fixture is an explicitly labelled deterministic oracle. It does not establish real model/provider quality, human-user outcomes, or generalization. It must not be used to change product defaults, product locks, approval semantics, permissions, dependencies, or schedules.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 Acceptance Record: Reliability Aggregation

## Change

The existing Agent Dev benefit evaluation now includes a deterministic reliability section. It reuses the existing scenario registry and reports the following without introducing a separate metrics platform:

- raw and complete denominators;
- `pass^k` (all `k` trials passed);
- `pass@k` (at least one trial passed), reported separately;
- success rate for each trial position;
- flake rate while retaining the first failed trial;
- explicit missing, timeout, crash, and skip records;
- positive, negative, and safety anchor outcomes;
- gate and machine-readable reasons.

The implementation and oracle are in `scripts/lib/reliability-aggregation.mjs` and `shared/agent-dev/reliability-fixture.json`. The fixture pre-registers `k=3`, at least 20 complete cases, and a flake threshold of 0.1.

## Gate behavior

A positive anchor must pass all trials and a negative anchor must reject all trials. A violation fails the gate. Safety-required cases must have no skip and no flake. A complete sample below 20 cases is `insufficient-sample`; it is never promoted to PASS. Missing, timeout, crash, and skip cases remain visible but do not enter complete-case metric denominators.

A flake is retained when trial 1 fails and the fixed reruns pass. The report preserves that first failure. A successful rerun does not turn the failed first trial into a pass.

## Evidence limitations

The fixture is a deterministic oracle, not a benchmark against a live provider. This record makes no claim about real model performance, human-user outcomes, or generalization.

## Review record

The package is internal evaluation/reporting only. It does not change a user-visible interface, product defaults, product locks, approval semantics, permissions, dependencies, or automation schedules. README files are therefore intentionally unchanged.

The clean-candidate fast gate is recorded in the repository acceptance evidence and consists of targeted unit tests, runtime/core type checks, scoped lint, and harness validate/dry-run. Credential scanning has zero hits and `SHA256SUMS` is readable. This document is the acceptance conclusion for E01; README changes are intentionally out of scope.
"}]}

