    oracle: 'deterministic-fixture',
    providerClaim: false,
    humanClaim: false,
    generalizationClaim: false,
    design: { k, minCases, flakeThreshold },
    raw: {
      caseCount: cases.length,
      trialCount: cases.reduce((sum, item) => sum + item.trials.length, 0),
      completeCaseCount: completeResults.length,
      incompleteCaseCount: incompleteResults.length,
    },
    metrics: {
      passPowerK: {
        numerator: passPowerNumerator,
        denominator: completeResults.length,
        rate: ratio(passPowerNumerator, completeResults.length),
      },
      passAtK: {
        numerator: passAtNumerator,
        denominator: completeResults.length,
